def uniquePaths(m, n):
    # 算法思路：动态规划，dp[i][j] 表示从左上角走到 (i,j) 的路径总数
    # 转移方程 dp[i][j] = dp[i-1][j] + dp[i][j-1]，即从上边或左边一步到达
    # 边界初始化：第一行与第一列都只有唯一一条路径
    # 时间复杂度 O(m*n)，空间复杂度 O(m*n)
    dp = [[0] * n for _ in range(m)]
    for i in range(m):
        dp[i][0] = 1  # 第一列只能一直向下走，路径数为 1
    for j in range(n):
        dp[0][j] = 1  # 第一行只能一直向右走，路径数为 1
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
    return dp[m - 1][n - 1]

