def minPathSum(grid):
    # 算法思路：动态规划，dp[i][j] 表示到达 (i,j) 时的最小路径和
    # 转移方程 dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]
    # 边界初始化：第一行只能从左累加，第一列只能从上累加
    # 时间复杂度 O(m*n)，空间复杂度 O(m*n)
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = grid[0][0]
    for j in range(1, n):
        dp[0][j] = dp[0][j - 1] + grid[0][j]  # 第一行只能向右走，路径唯一
    for i in range(1, m):
        dp[i][0] = dp[i - 1][0] + grid[i][0]  # 第一列只能向下走，路径唯一
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j]
    return dp[m - 1][n - 1]

