def minDistance(word1, word2):
    # 算法思路：动态规划，dp[i][j] 表示 word1 前 i 个字符转换为 word2 前 j 个字符的最少操作数
    # 字符相等时继承 dp[i-1][j-1]，否则取插入、删除、替换三种操作的最小值再加一
    # 边界初始化：dp[i][0]=i 表示删除 i 个字符，dp[0][j]=j 表示插入 j 个字符
    # 时间复杂度 O(m*n)，空间复杂度 O(m*n)
    m, n = len(word1), len(word2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i  # word2 为空，只能全部删除
    for j in range(n + 1):
        dp[0][j] = j  # word1 为空，只能全部插入
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # 字符相等，无需额外操作
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1  # 删除、插入、替换取最小
    return dp[m][n]

