def longestCommonSubsequence(text1, text2):
    # 算法思路：动态规划，dp[i][j] 表示 text1 前 i 个字符与 text2 前 j 个字符的最长公共子序列长度
    # 当前字符相等则 dp[i][j] = dp[i-1][j-1] + 1，否则取上方与左方的较大值
    # 易错点：下标错位，text1[i-1] 对应第 i 个字符，dp 多开一行一列
    # 时间复杂度 O(m*n)，空间复杂度 O(m*n)
    m, n = len(text1), len(text2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i - 1] == text2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1  # 字符相等，公共子序列长度加一
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])  # 不相等，继承两侧的较大值
    return dp[m][n]

